function c1WallConnections(x,y,z){return [[1,0],[-1,0],[0,1],[0,-1]].map(([dx,dz])=>{let b=get(x+dx,y,z+dz),d=D[b];return !!d&&(!!d.c1Wall||d.farmKind==='gate'||solid(b)&&!d.partial&&!d.shape&&!d.door&&!d.plant&&!d.liquid);});}
function c1WallBoxes(x,y,z,collision=false){let c=c1WallConnections(x,y,z),a=D[get(x,y+1,z)],covered=!!a&&!a.partial&&!a.plant&&!a.liquid&&!a.shape,straight=c[0]&&c[1]&&!c[2]&&!c[3]||c[2]&&c[3]&&!c[0]&&!c[1],height=collision?1.5:covered?1:.875;
 if(straight&&!covered)return c[0]?[[0,0,.3125,1,height,.6875]]:[[.3125,0,0,.6875,height,1]];
 let boxes=[[.25,0,.25,.75,collision?1.5:1,.75]];if(c[0])boxes.push([.75,0,.3125,1,height,.6875]);if(c[1])boxes.push([0,0,.3125,.25,height,.6875]);if(c[2])boxes.push([.3125,0,.75,.6875,height,1]);if(c[3])boxes.push([.3125,0,0,.6875,height,.25]);return boxes;
}
