function c1WallUV(a,f,tex){let r=rectUV(tex),u=f<2?[a[2],1-a[4],a[5],1-a[1]]:f<4?[a[0],a[2],a[3],a[5]]:[a[0],1-a[4],a[3],1-a[1]];return [[u[0],u[3]],[u[2],u[3]],[u[2],u[1]],[u[0],u[1]]].map(v=>[r[0]+v[0]*r[2],r[1]+v[1]*r[3]]);}
function c1WallMesh(out,x,y,z,b){let d=D[b];if(!d?.c1Wall)return false;for(let a of c1WallBoxes(x,y,z))for(let f=0;f<6;f++)emit(out,FACES[f].v.map(v=>[x+a[0]+v[0]*(a[3]-a[0]),y+a[1]+v[1]*(a[4]-a[1]),z+a[2]+v[2]*(a[5]-a[2])]),d.tex,FACES[f].shade,vertexLight(x,y,z,f),0,c1WallUV(a,f,d.tex));return true;}
function c1CraftStack(r){let result=makeStack(r.out,r.n);if(r.c1Upgrade){let input=craftGrid.find(s=>s?.k===r.c1Upgrade);if(!input)throw Error('Missing upgrade base');let damage=Math.max(0,I[input.k].dur-(input.wear??I[input.k].dur));result.wear=Math.max(1,Math.min(I[r.out].dur,I[r.out].dur-damage));}return result;}
